<script setup lang="ts">
import { computed } from 'vue'
import { Check, Quote, Trash2 } from 'lucide-vue-next'
import { useAppStore } from '../../stores/app'
import { deletePublicReview } from '../../services/workspace.service'
const app = useAppStore(); const business = computed(() => app.selectedBusiness); const reviews = computed(() => business.value.reviews); async function toggle(id: number) { const nextReviews = reviews.value.map((review) => review.id === id ? { ...review, approved: !review.approved } : review); app.updateBusiness({ reviews: nextReviews }); await app.persistBusiness({ ...business.value, reviews: nextReviews }) } async function remove(id: number) { const nextReviews = reviews.value.filter((review) => review.id !== id); await deletePublicReview(business.value.id, id); app.updateBusiness({ reviews: nextReviews }); await app.persistBusiness({ ...business.value, reviews: nextReviews }) }
</script>
<template><div class="reviews-page"><div class="review-summary"><Quote :size="22" /><span><strong>{{ reviews.filter((review) => review.approved).length }}</strong><small>publicadas en {{ business.name }}</small></span><span><strong>{{ reviews.filter((review) => !review.approved).length }}</strong><small>pendientes de revision</small></span></div><div class="reviews-grid"><article v-for="review in reviews" :key="review.id" class="review-admin-card"><div class="review-admin-head"><span class="person-avatar">{{ review.name.slice(0, 2).toUpperCase() }}</span><div><strong>{{ review.name }}</strong><small>{{ review.createdAt }}</small></div><span class="stars">{{ '★'.repeat(review.rating) }}{{ '☆'.repeat(5 - review.rating) }}</span></div><p>{{ review.text }}</p><div><button class="button secondary" @click="toggle(review.id)"><Check :size="14" /> {{ review.approved ? 'Publicada' : 'Publicar' }}</button><button class="icon-danger" aria-label="Eliminar reseña" @click="remove(review.id)"><Trash2 :size="15" /></button></div></article><p v-if="!reviews.length" class="empty">Todavia no hay resenas.</p></div></div></template>
